    if (!batch) throw new AppError(404, "PAYMENT_BATCH_NOT_FOUND", "Payment batch not found.");
    const payslips = await Payslip.findAll({ where: { payment_batch_id: batchId }, include: payslipIncludes, order: [["employee_name", "ASC"]] });
